library(shiny)

ui <- fluidPage(
  tags$head(tags$style(HTML("
    body { background-color: #111; color: white; }

    .big-btn {
      flex: 1;
      margin: 2px;
      height: 80px;
      font-size: 20px;
      font-weight: bold;
      border-radius: 14px;
    }

    .section-title {
      font-size: 22px;
      margin-top: 14px;
      color: white;
    }

    .holder-box {
      padding: 12px;
      border-radius: 12px;
      text-align: center;
      font-size: 20px;
      font-weight: bold;
      margin-bottom: 10px;
      border: 2px solid white;
      background-color: rgba(255,255,255,0.1);
    }

    #carrier_m { background-color: white; color: #971f07; }
    #turnover_m { background-color: white; color: #0aaecf; }
    #goal_m { background-color: white; color: #cf8e0a; }
    #carrier_f { background-color: #971f07; color: white; }
    #turnover_f { background-color: #0aaecf; color: white; }
    #goal_f { background-color: #cf8e0a; color: white; }

    .stat-box {
      padding: 10px;
      border-radius: 10px;
      margin-bottom: 8px;
      text-align: center;
      font-size: 16px;
      font-weight: bold;
      border: 2px solid white;
      background-color: rgba(255,255,255,0.1);
    }

  "))),

  titlePanel("Bristol Mixed Pass Tracker"),

  # Current Holder
  div(class="section-title", "Current Disc Holder"),
  div(class="holder-box", textOutput("current_holder")),

  # Disk Carrier
  div(class="section-title", "Disk Carrier"),
  div(style="display:flex; justify-content:space-between;",
      actionButton("carrier_m", "M", class="big-btn"),
      actionButton("carrier_f", "F", class="big-btn")
  ),

  # Turnover Target
  div(class="section-title", "Turnover Target"),
  div(style="display:flex; justify-content:space-between;",
      actionButton("turnover_m", "M", class="big-btn"),
      actionButton("turnover_f", "F", class="big-btn")
  ),

  # Goal Scorer
  div(class="section-title", "Goal Scorer"),
  div(style="display:flex; justify-content:space-between;",
      actionButton("goal_m", "M", class="big-btn"),
      actionButton("goal_f", "F", class="big-btn")
  ),

  br(),

  # Live stats
  div(class="section-title", "Live Stats"),
  fluidRow(
    column(6, div(class="stat-box", textOutput("count_mm"))),
    column(6, div(class="stat-box", textOutput("count_mf")))
  ),
  fluidRow(
    column(6, div(class="stat-box", textOutput("count_fm"))),
    column(6, div(class="stat-box", textOutput("count_ff")))
  ),
  fluidRow(
    column(6, div(class="stat-box", textOutput("count_turnovers"))),
    column(6, div(class="stat-box", textOutput("count_assists")))
  ),

  br(),
  actionButton("undo", "Undo Last Action", class="btn-danger big-btn"),
  br(),
  actionButton("download", "Download Game Data", class="btn-primary big-btn"),
  br(), br(),
  actionButton("reset", "Reset All", class="btn-warning big-btn"),

  # JS for CSV download
  tags$script(HTML("
    Shiny.addCustomMessageHandler('downloadData', function(data) {
      var blob = new Blob([data.csv], { type: 'text/csv;charset=utf-8;' });
      var link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = data.filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    });
  "))
)

server <- function(input, output, session) {

  rv <- reactiveValues(
    data = data.frame(Timestamp=character(),
                      From=character(),
                      To=character(),
                      Outcome=character(),
                      stringsAsFactors=FALSE),
    current_from = NULL,
    history = list() # stores past states for undo
  )

  # Display current holder
  output$current_holder <- renderText({
    if(is.null(rv$current_from)) {
      "None (Start of possession)"
    } else {
      paste("Current:", rv$current_from)
    }
  })

  # Function to log a pass/event
  log_pass <- function(to, outcome) {
    # Save current state for undo
    rv$history <- c(rv$history, list(list(
      last_from = rv$current_from,
      last_data = rv$data
    )))

    new_row <- data.frame(
      Timestamp = as.character(Sys.time()),
      From = rv$current_from,
      To = to,
      Outcome = outcome,
      stringsAsFactors = FALSE
    )
    rv$data <- rbind(rv$data, new_row)

    # Update current_from
    rv$current_from <- if(outcome == "Completed") to else NULL
  }

  # Disk Carrier buttons
  observeEvent(input$carrier_m, {
    # Save current state for undo
    rv$history <- c(rv$history, list(list(
      last_from = rv$current_from,
      last_data = rv$data
    )))

    if(is.null(rv$current_from)) {
      rv$current_from <- "M"
    } else {
      log_pass("M","Completed")
      rv$current_from <- "M"
    }
  })

  observeEvent(input$carrier_f, {
    rv$history <- c(rv$history, list(list(
      last_from = rv$current_from,
      last_data = rv$data
    )))

    if(is.null(rv$current_from)) {
      rv$current_from <- "F"
    } else {
      log_pass("F","Completed")
      rv$current_from <- "F"
    }
  })


  # Turnover buttons
  observeEvent(input$turnover_m, { if(!is.null(rv$current_from)) log_pass("M","Turnover") })
  observeEvent(input$turnover_f, { if(!is.null(rv$current_from)) log_pass("F","Turnover") })

  # Goal buttons
  observeEvent(input$goal_m, { if(!is.null(rv$current_from)) log_pass("M","Assist") })
  observeEvent(input$goal_f, { if(!is.null(rv$current_from)) log_pass("F","Assist") })

  # Undo last action
  observeEvent(input$undo, {
    if(length(rv$history) > 0) {
      last <- rv$history[[length(rv$history)]]
      rv$history <- rv$history[-length(rv$history)]
      rv$data <- last$last_data
      rv$current_from <- last$last_from
    }
  })

  # Reset all
  observeEvent(input$reset, {
    rv$data <- data.frame(Timestamp=character(),
                          From=character(),
                          To=character(),
                          Outcome=character(),
                          stringsAsFactors=FALSE)
    rv$current_from <- NULL
    rv$history <- list()
  })

  # Live stats
  output$count_mm <- renderText({ paste("M → M:", sum(rv$data$From=="M" & rv$data$To=="M" & rv$data$Outcome=="Completed")) })
  output$count_mf <- renderText({ paste("M → F:", sum(rv$data$From=="M" & rv$data$To=="F" & rv$data$Outcome=="Completed")) })
  output$count_fm <- renderText({ paste("F → M:", sum(rv$data$From=="F" & rv$data$To=="M" & rv$data$Outcome=="Completed")) })
  output$count_ff <- renderText({ paste("F → F:", sum(rv$data$From=="F" & rv$data$To=="F" & rv$data$Outcome=="Completed")) })
  output$count_turnovers <- renderText({ paste("Turnovers:", sum(rv$data$Outcome=="Turnover")) })
  output$count_assists <- renderText({ paste("Assists:", sum(rv$data$Outcome=="Assist")) })

  # Download CSV
  observeEvent(input$download, {
    csv <- paste(capture.output(write.csv(rv$data, row.names=FALSE)), collapse="\n")
    filename <- paste0("ultimate_pass_data_", format(Sys.time(), "%Y-%m-%d_%H-%M-%S"), ".csv")
    session$sendCustomMessage("downloadData", list(csv=csv, filename=filename))
  })

}

shinyApp(ui, server)
